  "cust_street_address" character varying(40),
  "cust_postal_code" character varying(10),
  "cust_city" character varying(30),
  "cust_state_province" character varying(10),
  "cust_country_id" character(2),
  "nls_language" character varying(3),
  "nls_territory" character varying(30),
  "credit_limit" numeric(9,2),
  "cust_email" character varying(40),
  "account_mgr_id" integer,
  "geo_longitude" numeric(9,6),
  "geo_latitude" numeric(9,6),
  "date_of_birth" date,
  "marital_status" character varying(20),
  "gender" character varying(1),
